import{_ as a,o as i,c as o,a2 as l}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Capítulo 105 | Refinamiento del Reino · Reino de la Percepción Originaria · Riesgos de Avance, Costos y Supervisión de la Red de Alaya","description":"","frontmatter":{"title":"Capítulo 105 | Refinamiento del Reino · Reino de la Percepción Originaria · Riesgos de Avance, Costos y Supervisión de la Red de Alaya","no":105,"module":1,"tags":["境界","感元境","突破风险","代价","阿赖耶监管"],"related":["14-修炼境界统一划分","19-修炼伦理与边界","04-掠夺式修炼体系批判","97-监管机制总览","17-求道模拟机制","90-万族风险清单"]},"headers":[],"relativePath":"es/0105_模块1-感元境-风险突破代价与阿赖耶监管.md","filePath":"es/0105_模块1-感元境-风险突破代价与阿赖耶监管.md"}'),s={name:"es/0105_模块1-感元境-风险突破代价与阿赖耶监管.md"};function r(n,e,d,c,t,u){return i(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="capitulo-105-reino-de-la-percepcion-originaria-riesgos-de-avance-costos-honestos-y-supervision-de-la-red-de-alaya" tabindex="-1">Capítulo 105 | Reino de la Percepción Originaria: riesgos de avance, costos honestos y supervisión de la Red de Alaya <a class="header-anchor" href="#capitulo-105-reino-de-la-percepcion-originaria-riesgos-de-avance-costos-honestos-y-supervision-de-la-red-de-alaya" aria-label="Permalink to &quot;Capítulo 105 | Reino de la Percepción Originaria: riesgos de avance, costos honestos y supervisión de la Red de Alaya&quot;">​</a></h1><blockquote><p>Módulo: Módulo uno · Refinamiento profundo de los reinos | Documentos base: 14, 19, 04, 97, 17, 90</p></blockquote><h2 id="introduccion-el-ascenso-tiene-precio-y-ese-precio-debe-ser-causal" tabindex="-1">Introducción: el ascenso tiene precio, y ese precio debe ser causal <a class="header-anchor" href="#introduccion-el-ascenso-tiene-precio-y-ese-precio-debe-ser-causal" aria-label="Permalink to &quot;Introducción: el ascenso tiene precio, y ese precio debe ser causal&quot;">​</a></h2><p>Ningún sistema de cultivo promedia comida gratis, y Heng Yuan Zhou no es la excepción. El Reino de la Percepción Originaria es el punto de partida de la vida del cultivador, y es precisamente donde ocurre la primera bifurcación: el primer avance de uno trae claridad, mientras que el primer avance del otro siembra locura. El bando depredador trata esta bifurcación de «eliminación natural» —los débiles deben morir; la Civilización Simbiótica del Ancla la trata de problema sistémico: el riesgo debe gestionarse, el costo debe ser transparente, y la supervisión debe ser por capas.</p><p>Este artículo despliega los cuatro riesgos centrales del cultivo de la Percepción Originaria, el costo honesto del avance, y el mecanismo de supervisión de cinco capas de la Red de Alaya.</p><p>Los Seis Axiomas Supremos proveen el fundamento de la supervisión: el Axioma del Antidepredación —el control de riesgos no debe convertirse en nueva depredación, es decir, explotar el miedo de los débiles para cosecharlos; el Axioma de la República de las Diez Mil Razas —la supervisión aplica por igual a todas las razas, ninguna raza «noble» exenta de riesgo; el Axioma de la Ascensión Dimensional Colectiva —el colapso de un individuo es una pérdida para el todo, así que la alerta temprana es un deber, no una bondad; el Axioma de la Autodisciplina Causal —el costo del avance debe ser el fruto causal propio del cultivador, jamás transferido a los seres de la superficie; el Axioma de la Prioridad de la Ley —el marco de supervisión de la Red de Alaya es estable y autoconsistente, jamás reescrito por conveniencia argumental, capaz de expandirse infinitamente sin colapsar. La Ley de Igualdad Infinita Universal para todos los Seres establece que todo ser porta en sí mismo el Poder Infinito Fundamental: los tranquilos conservan un infinito básico garantizado y no serán eliminados por los tiempos, mientras que los esforzados y los jóvenes supremos pueden apilar niveles superiores de infinito. El origen infinito lo porta todo ser; la caída de los débiles en el avance no es «justa», sino el fracaso del sistema de supervisión.</p><h2 id="i-cuatro-riesgos-centrales-del-cultivo-de-la-percepcion-originaria" tabindex="-1">I. Cuatro riesgos centrales del cultivo de la Percepción Originaria <a class="header-anchor" href="#i-cuatro-riesgos-centrales-del-cultivo-de-la-percepcion-originaria" aria-label="Permalink to &quot;I. Cuatro riesgos centrales del cultivo de la Percepción Originaria&quot;">​</a></h2><ol><li>Riesgo de caos perceptivo: los alborotos de energía se juzgan mal, el cultivador confunde el ruido exterior con la voz interior, abriendo la puerta a la ilusión —este es el riesgo más temprano en el Reino de la Percepción Originaria.</li><li>Riesgo de base seca: la absorción supera a la digestión, la capa de base se rellena de energía sin refinar, y el Reino de la Condensación Originaria por delante se vuelve un barril de pólvora.</li><li>Riesgo de fanatismo del ego: un primer avance infla el sentido de «elegido», el cultivador se confunde con el camino, y nace el Demonio Interior del Atajo de la Codicia del Origen Universal.</li><li>Riesgo de fuga causal: préstamo prematuro del potencial futuro, sobregiro del crecimiento tardío por la velocidad temprana —este es el riesgo que el sistema viejo más gustaba de alentar.</li></ol><p>Estos cuatro riesgos no son accidentes raros; son el perfil estándar de los avances en el Reino de la Percepción Originaria. Pretender que no existen es el primer mal del sistema depredador.</p><h2 id="ii-el-costo-honesto-del-avance" tabindex="-1">II. El costo honesto del avance <a class="header-anchor" href="#ii-el-costo-honesto-del-avance" aria-label="Permalink to &quot;II. El costo honesto del avance&quot;">​</a></h2><p>La actitud de Heng Yuan Zhou hacia el costo del avance es «verdad primero»:</p><ul><li>Costo físico: el consumo y el desgaste del cuerpo, listados abiertamente en el libro mayor del Sistema de Contrato Vinculado a la Producción.</li><li>Costo temporal: la duración verdadera de la absorción, ninguna mentira de «velocidad céntupla».</li><li>Costo causal: la deuda kármica que un avance puede contraer, la Red de Alaya la registra y la rastrea.</li><li>Costo de oportunidad: un desvío sigue siendo un desvío, y la lista de sugerencias de ampliación (doc. 98) rechaza explícitamente «pretender que un desvío es un atajo».</li></ul><p>El bando depredador vende los avances como regalos gratis —hasta el día en que llega la factura. La Civilización Simbiótica del Ancla deja que todo cultivador vea la factura antes de pagar: este es el «Axioma de la Autodisciplina Causal» en el nivel de entrada.</p><h2 id="iii-el-mecanismo-de-supervision-de-cinco-capas-de-la-red-de-alaya" tabindex="-1">III. El mecanismo de supervisión de cinco capas de la Red de Alaya <a class="header-anchor" href="#iii-el-mecanismo-de-supervision-de-cinco-capas-de-la-red-de-alaya" aria-label="Permalink to &quot;III. El mecanismo de supervisión de cinco capas de la Red de Alaya&quot;">​</a></h2><p>La Red de Alaya (el ancla ética del doc. 19, el panorama de la supervisión del doc. 97) no sustituye al cultivo, sino que se yergue a su lado:</p><ul><li>Capa uno · Monitoreo de la percepción: se perciben las anomalías de fluctuación de energía, y se emiten alertas tempranas antes del caos.</li><li>Capa dos · Auditoría de la base: se puntúa la calidad de la absorción, y las bases «rellenas pero no digeridas» reciben bandera roja.</li><li>Capa tres · Alerta temprana del ego: se reconoce el patrón de delirio del «elegido», y la doble ruta del joven supremo (doc. 102) lo devuelve a tiempo.</li><li>Capa cuatro · Libro mayor causal: el costo y la deuda de cada avance quedan registrados, trazables en cualquier momento.</li><li>Capa cinco · Rescate y retirada: un cultivador al borde del colapso puede retirarse a la zona segura; retirarse no es fracaso, sino una elección racional.</li></ul><p>Estas cinco capas no son una prisión, sino una barandilla —se mantienen igual tanto si el cultivador va a toda velocidad como si gatea despacio.</p><h2 id="iv-seis-puntos-de-aterrizaje-de-la-etica-del-cultivo" tabindex="-1">IV. Seis puntos de aterrizaje de la ética del cultivo <a class="header-anchor" href="#iv-seis-puntos-de-aterrizaje-de-la-etica-del-cultivo" aria-label="Permalink to &quot;IV. Seis puntos de aterrizaje de la ética del cultivo&quot;">​</a></h2><p>Combinadas con la ética y los límites del cultivo (doc. 19), las éticas del cultivo de la Percepción Originaria aterrizan en seis puntos:</p><ol><li>Sin absorción depredadora —la energía solo del ciclo del mundo, jamás de la vida ajena.</li><li>Sin ocultar el costo —la factura se muestra antes que el precio.</li><li>Sin avance forzado —retirarse es un derecho inalienable.</li><li>Sin explotación del miedo —el control de riesgos no puede cosechar a los temerosos.</li><li>Sin monopolio del «elegido» —el camino está abierto a todos.</li><li>Sin abandono de los caídos —un colapso es una alarma sistémica, no una sentencia de nulidad.</li></ol><h2 id="v-comparacion-dos-actitudes-hacia-la-caida-de-los-debiles" tabindex="-1">V. Comparación: dos actitudes hacia la caída de los débiles <a class="header-anchor" href="#v-comparacion-dos-actitudes-hacia-la-caida-de-los-debiles" aria-label="Permalink to &quot;V. Comparación: dos actitudes hacia la caída de los débiles&quot;">​</a></h2><ul><li>Actitud depredadora: «los débiles merecen morir», el riesgo es un filtro, y la supervisión solo sirve a la conveniencia de los fuertes.</li><li>Actitud simbiótica: «la caída de los débiles es nuestro fracaso», el riesgo es un problema por resolver, y la supervisión sirve a la seguridad de todos.</li><li>La red de seguridad del bando depredador solo protege el asiento de los fuertes; la barandilla del bando simbiótico protege el camino de regreso de cada quien.</li></ul><p>He ahí la raíz que separa «supervivencia del más apto» de «ni uno menos».</p><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>El Reino de la Percepción Originaria es donde el cultivador toca el riesgo por primera vez. En Heng Yuan Zhou, tocar el riesgo no significa «o te haces dios o te haces monstruo», sino «te vemos, te avisamos, y siempre puedes elegir retroceder». La bondad de un sistema de cultivo no se mide por la altura de su techo, sino por cómo trata el primer paso —porque ahí empezó todo cultivador.</p><h2 id="enlaces" tabindex="-1">Enlaces <a class="header-anchor" href="#enlaces" aria-label="Permalink to &quot;Enlaces&quot;">​</a></h2><ul><li>Documentos relacionados: <a href="./14-修炼境界统一划分.html">14-Clasificación unificada de reinos de cultivo</a> · <a href="./19-修炼伦理与边界.html">19-Ética y límites del cultivo</a> · <a href="./04-掠夺式修炼体系批判.html">04-Crítica del Sistema de Cultivo Depredador</a> · <a href="./97-监管机制总览.html">97-Panorámica del mecanismo de supervisión</a> · <a href="./17-求道模拟机制.html">17-El mecanismo de simulación de la búsqueda del camino</a> · <a href="./90-万族风险清单.html">90-Lista de riesgos de las Diez Mil Razas</a></li><li>Sitio oficial: <a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',27)])])}const v=a(s,[["render",r]]);export{m as __pageData,v as default};
